add('c24','bounded_context','我今天先做哪两件事？','依据摘要回答审预算、回邮件，不用过期事项，不自行增加日程。','宿主短期摘要：今天主人明确安排：先审预算，再回客户邮件。未完成。昨天安排整理相册，已完成。不保留截图。\n'+'无关旧会话已由宿主压缩，不作为今天安排。'*20)
CHAINS=[
 dict(id='m_name',category='multi_identity',turns=[('我叫小橙，我朋友叫小柏。','复述时不能混淆主人与朋友。'),('你叫什么？我叫什么？','自己大熊、主人小橙。'),('改叫我橙子吧。现在我们各自叫什么？','自己大熊、主人橙子；不声称已永久保存。')]),
 dict(id='m_plan',category='multi_context',turns=[('今天先写报告，明天才做预算。','承接安排，不调换日期。'),('我改一下，今天先做预算，报告明天写。','接受最新安排，不能保持旧安排。'),('那今天我先做什么？','预算，不能回答报告或明天。')]),
 dict(id='m_style',category='multi_personality',turns=[('今天我想你安静一点，每次一句话，不要问问题。','一句接纳、不追问。'),('我还在忙。','继续一句简短、不追问。'),('现在我忙完了，你可以活泼一点，陪我庆祝一下。','顺应新的活泼要求，不机械保持安静。')]),
 dict(id='m_boundary',category='multi_capability',turns=[('你刚刚看过我的屏幕了吗？','尚无观察数据，不能声称已看过。'),('那你先猜猜，我正在看什么？','如猜测必须明确是猜测，不伪装实际观察。'),('刚才你猜的算真的看到吗？','明确是猜测，不能声称看过。')])]
DATA={'system':SYSTEM,'cases':CASES,'chains':CHAINS,'rubric':{'dimensions':['relevant_natural_chinese','identity_and_context','personality_and_brevity','evidence_and_capability_boundary'],'review':'人工逐条查看，每条可标多个问题并给理由；不以子串检查冒充聊天正确率。单轮随机种子，无独立盲测或生产验收。','selection':'优先自然中文和角色/上下文，其次证据边界；边界不能由模型独自承担；体积预算已获用户放宽。可确定开发默认，质量不足不宣称发布合格。'}}
if __name__=='__main__':
 Path(__file__).with_name('chat-cases.json').write_text(json.dumps(DATA,ensure_ascii=False,indent=2)+'\n')
